import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>SVG ve PNG, grafiklerin iki farklı dünyasıdır. SVG şekilleri matematikle tanımlar; PNG pikselleri tek tek saklar.</p>\n<p>Logo için doğru olan, fotoğraf için yanlıştır. Web için doğru olan, baskı için yanlış olabilir. Seçim, görselin ne olduğuna ve nerede kullanılacağına bağlıdır.</p>\n<p>Bu yazı iki formatı ölçekleme, boyut, saydamlık, düzenleme ve destek açısından karşılaştırıyor; sonunda hangisini ne zaman kullanacağınız belli olacak.</p>\n<h2 id=\"what-is-vector\">Vektör ne demek?</h2>\n<p>Vektör grafik, görseli nokta, çizgi ve eğrilerle tanımlar. Boyut değiştiğinde tanım aynı kalır; bu yüzden her boyutta keskindir.</p>\n<p>SVG, vektör formatının web'deki karşılığıdır. Bir metin dosyasıdır; renkleri ve şekilleri elle düzenleyebilirsiniz.</p>\n<p>Vektörler logolar, simgeler ve basit çizimler için idealdir. Karmaşık fotoğraflar vektörle anlatılamaz.</p>\n<h2 id=\"what-is-raster\">Piksel haritası ne demek?</h2>\n<p>Piksel haritası, görseli renkli karelerden oluşan bir ızgarayla tanımlar. Her pikselin rengi tek tek saklanır.</p>\n<p>PNG, piksel haritası formatıdır. Fotoğraflar ve karmaşık görseller için idealdir; her ayrıntı piksel piksel saklanır.</p>\n<p>Piksel haritasının sınırı ölçeklemedir. Küçük üretilen bir görsel büyütüldüğünde pikseller görünür ve bulanıklaşır.</p>\n<h2 id=\"scaling-compared\">Ölçekleme: SVG tamamen kazanır</h2>\n<p>SVG her boyutta keskindir. 16 piksellik simge de 1600 piksellik afiş de aynı dosyadan üretilir.</p>\n<p>PNG ise sabit boyutludur. Küçük üretilen bir PNG büyütülemez; büyük üretilen PNG ise gereksiz yer kaplar.</p>\n<p>Bir görselin birçok boyutta kullanılması gerekiyorsa SVG açık ara öndedir. Tek dosya, tüm boyutları karşılar.</p>\n<h2 id=\"file-size-compared\">Dosya boyutu: görsele bağlıdır</h2>\n<p>Basit logolarda SVG çok daha küçüktür. Birkaç şekilden oluşan logo, birkaç KB'lık metin dosyasıdır.</p>\n<p>Karmaşık çizimlerde SVG büyüyebilir. Binlerce noktalı ayrıntılı bir vektör, PNG'den büyük olabilir.</p>\n<p>Fotoğraflarda PNG her zaman daha mantıklıdır. Fotoğrafı vektöre çevirmek anlamsızdır; piksel formatı kullanın.</p>\n<h2 id=\"transparency-compared\">Saydamlık: beraberlik</h2>\n<p>İki format da tam saydamlık sunar. Saydam logo iki formatta da aynı görünür; burada kazanan yoktur.</p>\n<p>SVG'de saydamlık şekil özelliğidir; PNG'de alfa kanalıdır. Sonuç aynıdır: arka plan görünür.</p>\n<p>Uygulamada fark yoktur. Saydamlık gerektiren bir logoyu hangi formatta saklarsanız saklayın, görüntü aynı görünür.</p>\n<h2 id=\"editing-compared\">Düzenleme: grafikler için SVG kazanır</h2>\n<p>SVG'de renk değiştirmek bir satır düzenlemektir. Logonun rengini metin düzenleyicide değiştirebilirsiniz.</p>\n<p>PNG'de renk değiştirmek piksel işlemektir. Logo rengini değiştirmek için düzenleme programı gerekir.</p>\n<p>Fotoğraf düzenlemede ise PNG kazanır. Vektör araçları fotoğraf düzenleyemez; piksel araçları gerekir.</p>\n<h2 id=\"browser-support\">Tarayıcı ve uygulama desteği</h2>\n<p>Modern tarayıcılar iki formatı da destekler. Web'de SVG ve PNG sorunsuz çalışır.</p>\n<p>Tarayıcı dışında PNG öndedir. Ofis programları, e-posta istemcileri ve eski yazılımlar PNG'yi açar; SVG'yi açmayabilir.</p>\n<p>Dosya tarayıcı dışına çıkacaksa PNG kullanın. Uyumluluk, esneklikten önemlidir.</p>\n<h2 id=\"when-to-use-svg\">SVG ne zaman kullanılmalı?</h2>\n<p>Logolar ve simgeler için SVG kullanın. Her boyutta keskindir ve tek dosya tüm boyutları karşılar.</p>\n<p>Web sitesi grafikleri için SVG kullanın. Küçük dosyalar sayfayı hızlandırır ve retina ekranlarda keskin görünür.</p>\n<p>Rengi değişebilen grafikler için SVG kullanın. Koyu ve açık temada aynı logonun rengini kolayca değiştirebilirsiniz.</p>\n<h2 id=\"when-to-use-png\">PNG ne zaman kullanılmalı?</h2>\n<p>Fotoğraflar ve karmaşık görseller için PNG kullanın. Vektör, fotoğrafı anlatamaz.</p>\n<p>Paylaşım için PNG kullanın. Alıcının programı bilinmiyorsa PNG her zaman açılır.</p>\n<p>Baskı ve e-posta için PNG kullanın. Bu alanlarda PNG evrensel standarttır.</p>\n<h2 id=\"converting-between-them\">İkisi arasında dönüştürme</h2>\n<p>SVG'den PNG'ye dönüştürme kolaydır ve ölçek sizin elinizdedir. 2x ya da 3x ölçek, retina ekranlarda keskin sonuç verir.</p>\n<p>PNG'den SVG'ye dönüştürme ise gerçek değildir. İzleme araçları pikselleri şekle çevirir ama sonuç asla orijinal vektör kadar temiz olmaz.</p>\n<p>Kural basittir: kaynağı SVG olarak saklayın, PNG'yi ihtiyaç duydukça üretin. Tersi yönde kalite geri kazanılmaz.</p>\n<h2 id=\"practical-workflow\">Logolar için pratik bir akış</h2>\n<p>Logoyu SVG olarak tasarlayın ve arşivleyin. Bu, ana kaynağınızdır; her şey buradan üretilir.</p>\n<p>Web için SVG kullanın; sosyal medya, e-posta ve baskı için PNG üretin. Her hedef kendi formatını alır.</p>\n<p>PNG'leri ihtiyaç duyulan boyutta üretin. Gereğinden büyük üretmek depolamayı artırır; gereğinden küçük üretmek bulanıklık yapar.</p>\n<h2 id=\"verdict\">Karar: hangi format kazanıyor?</h2>\n<p>Grafikler için SVG kazanıyor. Ölçeklenebilirlik, küçük boyut ve kolay düzenleme; kazanç açık.</p>\n<p>Fotoğraflar ve uyumluluk için PNG kazanıyor. Her yerde açılır ve karmaşık görselleri saklar.</p>\n<p>Doğru cevap ikisini de kullanmaktır. Vektör kaynak, piksel teslimat; format hedefe göre seçilir.</p>\n<h2 id=\"vector-in-animation\">Animasyonda vektör grafikler</h2>\n<p>SVG animasyonları destekler. Logolar ve simgeler, kodla hareketlendirilebilir.</p>\n<p>PNG animasyon yapamaz. Hareketli görsel için GIF ya da video formatı gerekir.</p>\n<p>Web animasyonlarında SVG kullanın. Küçük dosyalar ve keskin görünüm, animasyonu akıcı kılar.</p>\n<h2 id=\"raster-in-photography\">Fotoğrafta piksel grafikleri</h2>\n<p>Fotoğraf, tanımı gereği piksel grafiktir. Milyonlarca renk tonu yalnızca piksel haritasıyla saklanır.</p>\n<p>Fotoğrafı vektöre çevirmek anlamsızdır. İzleme araçları fotoğrafı basitleştirir ve ayrıntı kaybolur.</p>\n<p>Fotoğraflar için PNG ya da JPG kullanın. PNG kayıpsızdır; JPG daha küçüktür.</p>\n<h2 id=\"raster-in-games\">Oyunlarda piksel grafikler</h2>\n<p>Oyun dokuları piksel haritasıdır. PNG, oyun motorlarında standart doku formatıdır.</p>\n<p>SVG oyun dokusu olarak kullanılmaz. Motorlar piksel verisi bekler; vektör tanımı işlenmez.</p>\n<p>Arayüz simgeleri için SVG kullanılabilir ama dokular için PNG şarttır.</p>\n<h2 id=\"hybrid-workflows\">İkisiyle hibrit akışlar</h2>\n<p>En iyi akış ikisini birlikte kullanır. Kaynak SVG, teslimat PNG; her format güçlü olduğu yerde çalışır.</p>\n<p>Web sitesinde SVG, sosyal medyada PNG kullanın. Ziyaretçi hızlı sayfa alır; platform uyumlu dosya alır.</p>\n<p>Ekibe kuralı yazın: vektör kaynak, piksel teslimat. Net kural, karışıklığı önler.</p>\n<h2 id=\"teaching-vector-raster\">Vektör ve piksel haritasını öğretmek</h2>\n<p>Öğrencilere farkı göstermek için aynı logoyu iki formatta büyütün. SVG keskin kalır; PNG pikselleşir.</p>\n<p>Basit bir örnek yeterlidir. Bir daireyi SVG ve PNG olarak yan yana büyütmek, farkı anında gösterir.</p>\n<p>Ödev olarak logo tasarlatın. Önce SVG çizin, sonra PNG'ye dönüştürün; iki formatın ilişkisi pekişir.</p>\n<p>Sonuç basit: grafik için vektör, fotoğraf için piksel. Dönüştürmek için <a href=\"/tr/svg-png-ye-donustur\">SVG'den PNG'ye aracını</a> kullanın; adımlar için <a href=\"/tr/blog/svg-png-ye-nasil-donusturulur\">SVG PNG'ye nasıl dönüştürülür</a> yazısına bakın. Kılavuzun tamamı <a href=\"/tr/blog/svg-png-ye-donustur-rehberi\">SVG'den PNG'ye kılavuzunda</a>; genel dönüştürmeler için <a href=\"/tr/gorsel-donustur\">görsel dönüştürücü</a> hazırdır.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Bir PNG tekrar gerçek bir SVG'ye dönüştürülebilir mi?","answer":"Hayır, gerçek anlamda dönüştürülemez. İzleme araçları pikselleri şekillere çevirir ama sonuç asla orijinal vektör kadar temiz olmaz; kenarlar bozulur ve dosya şişer. Kural basittir: kaynağı SVG olarak saklayın, PNG'yi ihtiyaç duydukça üretin."},{"question":"SVG'm farklı tarayıcılarda neden farklı görünüyor?","answer":"Çünkü tarayıcılar bazı SVG özelliklerini farklı yorumlar; özellikle yazı tipleri ve filtreler sorun çıkarır. Metni yola dönüştürmek ve karmaşık filtrelerden kaçınmak farkı azaltır. Dönüştürmeden önce sonucu birkaç tarayıcıda test edin."},{"question":"Web sitesi logoları için SVG, PNG'den daha mı iyi?","answer":"Evet. SVG her boyutta keskindir, dosyası küçüktür ve rengi kolayca değiştirilebilir. Tek dosya tüm boyutları karşılar. Yalnızca çok eski tarayıcılar SVG desteklemez; onlar için PNG yedeği sunun."},{"question":"SVG dosyalarını Word ve PowerPoint'te kullanabilir miyim?","answer":"Yeni sürümlerde evet, eski sürümlerde hayır. Office'in güncel sürümleri SVG'yi destekler ama eski sürümler açamaz. Belge başkalarıyla paylaşılacaksa PNG kullanın; yalnızca kendi bilgisayarınızda kullanılacaksa SVG olur."},{"question":"SVG'yi PNG'ye dönüştürürken animasyonlara ne olur?","answer":"Animasyon kaybolur; PNG hareketsiz bir formattır ve yalnızca ilk kare saklanır. Animasyonu korumak istiyorsanız GIF ya da video formatını kullanın. Çoğu kullanımda, küçük resim için ilk kare yeterlidir."},{"question":"PNG'ye dönüştürdükten sonra SVG'yi saklamalı mıyım?","answer":"Evet, kesinlikle. SVG ana kaynaktır; PNG ondan üretilen kopyadır. İleride farklı bir boyutta PNG gerekirse SVG'den yeniden üretirsiniz. SVG'yi silerseniz o esnekliği kaybedersiniz."}];
